pub fn menu(ui:&mut egui::Ui,session:u64,revision:u64,target:Target,intents:&mut Vec<crate::views::Intent>){
 let state=ui.ctx().data(|d|d.get_temp::<MenuState>(egui::Id::new(MENU))).unwrap_or_default();
 if ui.button(crate::i18n::tr(ui,"Windowed Projector")).on_hover_text(crate::i18n::tr(ui,"Open this video view in a separate modeless window. Audio routing is unchanged.")).clicked(){intents.push(crate::views::Intent::Projector(Action::Open{session,revision,target,monitor:None,topology:state.topology}));ui.close_menu();}
 ui.menu_button(crate::i18n::tr(ui,"Fullscreen Projector"),|ui|{if state.monitors.is_empty(){ui.label(crate::i18n::tr(ui,"Refresh monitors to select an actual display."));}for monitor in &state.monitors{let name=format!("{} · {}×{} @ {},{}",monitor.name,monitor.width,monitor.height,monitor.x,monitor.y);if ui.button(name).on_hover_text(crate::i18n::tr(ui,"Move a new projector to this display, then enter borderless fullscreen.")).clicked(){intents.push(crate::views::Intent::Projector(Action::Open{session,revision,target,monitor:Some(monitor.id.clone()),topology:state.topology}));ui.close_menu();}}if ui.add_enabled(state.refresh,egui::Button::new(crate::i18n::tr(ui,"Refresh Projector Monitors"))).on_hover_text(crate::i18n::tr(ui,"Enumerate current physical display names and geometry on the I/O worker.")).clicked(){intents.push(crate::views::Intent::Projector(Action::Refresh{session}));ui.close_menu();}});
}
